1|// Persisted music prefs: style only. Storage can throw (private
2|// mode), so every access is guarded and falls back. Old values with
3|// mode or soundtrackId load safely: unknown fields are ignored.
4|import type { PersistedMusicPrefs } from "@/core/music";
5|
6|export const MUSIC_PREFS_KEY = "lectoria.music.v1";
7|
8|export function loadMusicPrefs(): PersistedMusicPrefs | null {
9|  try {
10|    if (typeof window === "undefined") return null;
11|    const raw = window.localStorage.getItem(MUSIC_PREFS_KEY);
12|    if (!raw) return null;
13|    const json: unknown = JSON.parse(raw);
14|    if (typeof json !== "object" || json === null) return null;
15|    const { style } = json as Record<string, unknown>;
16|    return {
17|      style: typeof style === "string" ? style : null,
18|    };
19|  } catch {
20|    return null;
21|  }
22|}
23|
24|export function saveMusicPrefs(prefs: PersistedMusicPrefs): void {
25|  try {
26|    if (typeof window === "undefined") return;
27|    window.localStorage.setItem(MUSIC_PREFS_KEY, JSON.stringify(prefs));
28|  } catch {
29|    // Private mode: playback continues without persistence.
30|  }
31|}

