49|// Client container: cues music on scene entry only, from the route id.
50|// Sub-page moves never reach the scheduler. Params can lag a render, so
51|// the last observed id is compared before every observe call.
52|export function Reader({ scenes, children }: { scenes: SlimScene[]; children: React.ReactNode }) {
53|  const routeParams = useParams();
54|  const param = routeParams?.sceneId;
55|  const routeSceneId = typeof param === "string" ? param : null;
56|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
57|  const [selection, setSelection] = useState<MusicSelection | null>(null);
58|  const [musicFailed, setMusicFailed] = useState(false);
59|  const [currentId, setCurrentId] = useState<string | null>(null);
60|  const [replayNonce, setReplayNonce] = useState(0);
61|  const [fadeSec, setFadeSec] = useState(0);
62|  const [playlistOn, setPlaylistOn] = useState(false);
63|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
64|  const schedRef = useRef<SchedulerState>(initScheduler());
65|  const historyRef = useRef<string[]>([]);
66|  const observedRef = useRef<string | null>(null);
67|  const liveRef = useRef({ routeSceneId, manifest, selection, currentId, byId, playlistOn });
68|  liveRef.current = { routeSceneId, manifest, selection, currentId, byId, playlistOn };
69|
70|  const nowSec = () => Date.now() / 1000;
71|
72|  const applyDecision = useCallback(
73|    (
74|      decision: {
75|        state: SchedulerState;
76|        switchToId: string | null;
77|        crossfadeSec: number;
78|      },
79|      opts?: { push?: boolean },
80|    ) => {
81|      // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
82|      // so bump a replay nonce the player effect listens to instead.
83|      const prevId = schedRef.current.currentId;
84|      schedRef.current = decision.state;
85|      if (decision.switchToId !== null) {
86|        setFadeSec(decision.crossfadeSec);
87|        if (decision.switchToId === prevId) {
88|          setReplayNonce((n) => n + 1);
89|        } else {
