97|      }
98|    },
99|    [],
100|  );
101|
102|  const persist = useCallback((next: MusicSelection) => {
103|    setSelection(next);
104|    saveMusicPrefs({ style: next.style });
105|  }, []);
106|
107|  const observe = useCallback(
108|    (sceneId: string) => {
109|      const st = liveRef.current;
110|      if (!st.manifest || !st.selection) return;
111|      const signal = st.byId.get(sceneId) ?? null;
112|      applyDecision(
113|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
114|          selection: st.selection,
115|          rng: Math.random,
116|        }, entryDwell()),
117|      );
118|    },
119|    [applyDecision],
120|  );
