139|      cancelled = true;
140|    };
141|  }, []);
142|
143|  // Scene entry: exactly one observe call per scene id, once the manifest
144|  // lands. The first scene cues at once, so it plays on the first press.
145|  useEffect(() => {
146|    const gate = nextSceneEntry({
147|      observedId: observedRef.current,
148|      routeId: routeSceneId,
149|      manifestReady: manifest !== null,
150|    });
151|    observedRef.current = gate.nextObservedId;
152|    if (gate.shouldObserve && routeSceneId) observe(routeSceneId);
153|  }, [routeSceneId, manifest, observe]);
154|
155|  useEffect(() => {
