157|    const timer = window.setInterval(() => {
158|      const st = liveRef.current;
159|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
160|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
161|      const signal = st.byId.get(sceneId) ?? null;
162|      applyDecision(
163|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
164|          selection: st.selection,
165|          rng: Math.random,
166|        }, entryDwell()),
167|      );
168|    }, 1000);
169|    return () => window.clearInterval(timer);
170|  }, [applyDecision]);
171|
172|  function skip() {
173|    const st = liveRef.current;
174|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
175|    const signal = st.byId.get(st.routeSceneId) ?? null;
176|    applyDecision(
177|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
178|        selection: st.selection,
179|        rng: Math.random,
180|      }),
181|    );
182|  }
183|
184|  // Previous: back to the last played track, held like a Next. With no
185|  // history the current track restarts from zero through the replay path,
186|  // including in playlist mode.
187|  function goPrev() {
188|    const st = liveRef.current;
189|    if (!st.manifest || !st.selection) return;
190|    if (st.playlistOn) {
191|      setReplayNonce((n) => n + 1);
192|      return;
193|    }
