211|    if (st.playlistOn) {
212|      const signal = (st.routeSceneId && st.byId.get(st.routeSceneId)) || null;
213|      applyDecision(
214|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
