import { describe, expect, it } from "vitest";
import { buildReaderModel, paginateScene } from "@/core/reader";
import { loadOzBook } from "@/server/books";
describe("measure", () => {
  it("prints page stats", () => {
    const { book, scenes } = loadOzBook();
    const model = buildReaderModel(book, { scenes });
    let max = 0; let maxId = ""; let total = 0; let n = 0;
    const lens: number[] = [];
    for (const ch of model.chapters) for (const s of ch.scenes) {
      const pages = paginateScene(s.paragraphs);
      for (const p of pages) {
        const words = p.paragraphs.reduce((a, q) => a + q.text.split(/\s+/).length, 0);
        lens.push(words); total += words; n++;
        if (words > max) { max = words; maxId = s.id; }
      }
    }
    lens.sort((a, b) => a - b);
    console.log("pages:", n, "max:", max, maxId, "p95:", lens[Math.floor(n*0.95)], "mean:", Math.round(total/n));
  });
});
EOF
