import { describe, expect, it } from "vitest";
import { writeFileSync } from "node:fs";
import { buildReaderModel, paginateScene } from "@/core/reader";
import { loadOzBook } from "@/server/books";
describe("fit", () => {
  it("dumps worst pages", () => {
    const { book, scenes } = loadOzBook();
    const model = buildReaderModel(book, { scenes });
    const rows: { id: string; words: number; paras: number; chars: number }[] = [];
    for (const ch of model.chapters) for (const s of ch.scenes) {
      for (const p of paginateScene(s.paragraphs)) {
        const words = p.paragraphs.reduce((a, q) => a + q.text.split(/\s+/).length, 0);
        const chars = p.paragraphs.reduce((a, q) => a + q.text.length, 0);
        rows.push({ id: s.id, words, paras: p.paragraphs.length, chars });
      }
    }
    rows.sort((a, b) => b.words - a.words);
    writeFileSync("/tmp/worst.json", JSON.stringify(rows.slice(0, 5), null, 1));
    console.log(JSON.stringify(rows.slice(0, 3)));
    // also longest chapter title
